// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { CGProgramFactory } from "./CGProgramFactory.sol";

/// @title CGOrganization — Groups multiple CGPrograms under one owner
/// @notice Created by CGRegistry. The owner can create programs on demand via CGProgramFactory.
contract CGOrganization is Ownable {
    string public name;
    CGProgramFactory public immutable programFactory;
    address[] public programs;
    mapping(address => bool) public isProgram;

    event ProgramCreated(address indexed program, string name, bool lockDistributions);

    error EmptyName();

    constructor(address owner_, string memory name_, CGProgramFactory programFactory_) Ownable(owner_) {
        name = name_;
        programFactory = programFactory_;
    }

    /// @notice Deploy a new CGProgram owned by this organization's owner.
    function createProgram(string calldata name_, bool lockDistributions_) external onlyOwner returns (address) {
        if (bytes(name_).length == 0) revert EmptyName();
        address addr = programFactory.createProgram(owner(), name_, lockDistributions_);
        programs.push(addr);
        isProgram[addr] = true;

        emit ProgramCreated(addr, name_, lockDistributions_);
        return addr;
    }

    function programCount() external view returns (uint256) {
        return programs.length;
    }

    /// @notice Paginated read of program addresses.
    function getPrograms(uint256 offset, uint256 limit) external view returns (address[] memory) {
        uint256 len = programs.length;
        if (offset >= len) return new address[](0);

        uint256 end = offset + limit;
        if (end > len) end = len;
        uint256 size = end - offset;

        address[] memory result = new address[](size);
        for (uint256 i = 0; i < size; i++) {
            result[i] = programs[offset + i];
        }
        return result;
    }
}

contracts/CGPaymaster.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { CGRegistry } from "./CGRegistry.sol";
import { CGOrganization } from "./CGOrganization.sol";

// ── Minimal ERC-4337 EntryPoint v0.7 interface ───────────────────────────────

interface IEntryPoint {
    function depositTo(address account) external payable;
    function withdrawTo(address payable withdrawAddress, uint256 withdrawAmount) external;
    function balanceOf(address account) external view returns (uint256);
}

// ── ERC-4337 PackedUserOperation struct (EntryPoint v0.7) ────────────────────

struct PackedUserOperation {
    address sender;
    uint256 nonce;
    bytes initCode;
    bytes callData;
    bytes32 accountGasLimits; //  [verificationGasLimit (16) | callGasLimit (16)]
    uint256 preVerificationGas;
    bytes32 gasFees; //          [maxPriorityFeePerGas (16) | maxFeePerGas (16)]
    bytes paymasterAndData;
    bytes signature;
}

enum PostOpMode {
    opSucceeded,
    opReverted,
    postOpReverted
}

// ─────────────────────────────────────────────────────────────────────────────

/// @title CGPaymaster — ERC-4337 v0.7 Paymaster for Chain.Giving gas sponsorship
///
/// @notice Sponsors gas for beneficiary and organization owner UserOperations.
///         Each organization has an independent ETH budget tracked on-chain.
///         The total ETH is held at the EntryPoint under this paymaster's deposit;
///         per-org accounting is maintained in the `orgBalance` mapping.
///         Validation is fully on-chain — no off-chain relayer or signing service needed.
///
/// @dev    paymasterAndData layout (EntryPoint v0.7):
///           [0  :20] paymaster address                       (set by wallet/bundler)
///           [20:36] paymasterVerificationGasLimit (uint128)  (set by wallet/bundler)
///           [36:52] paymasterPostOpGasLimit       (uint128)  (set by wallet/bundler)
///           [52:72] sponsoring org address (20 bytes)        ← our paymasterData
///
///         Sponsored calls must use one of two outer selectors:
///           • execute(address,uint256,bytes)  — SimpleAccount / Coinbase Smart Wallet  (0xb61d27f6)
///           • execute(bytes32,bytes)          — ERC-7579 single execution / Kernel v3 (0xe9ae5c53)
///
///         The resolved call target must belong to the sponsoring org — checked by walking
///         the on-chain ownership chain: org → program → token/distribution/crowdfunding.
///
/// @dev    Management model:
///           • By default the CGPaymaster owner (= CGRegistry deployer) manages every org's stash.
///           • An org can opt into self-management via `transferManagement`.
///           • Only the current manager may `withdraw` or re-`transferManagement` an org's budget.
contract CGPaymaster is Ownable {
    // ── Outer-selector constants ──────────────────────────────────────────────

    /// @dev keccak256("execute(address,uint256,bytes)")[0:4]
    bytes4 private constant EXECUTE_SIMPLE = 0xb61d27f6;
    /// @dev keccak256("execute(bytes32,bytes)")[0:4] — ERC-7579 modular accounts
    bytes4 private constant EXECUTE_ERC7579 = 0xe9ae5c53;

    // ── paymasterAndData layout (v0.7) ───────────────────────────────────────

    uint256 private constant ORG_DATA_OFFSET = 52;
    uint256 private constant ORG_DATA_END = 72;

    // ── SimpleAccount execute(address,uint256,bytes) layout ──────────────────
    //
    //   [0  :  4] outer selector
    //   [4  : 36] target          (address, right-aligned in 32 bytes)
    //   [36 : 68] value           (uint256)
    //   [68 :100] data offset     (canonical = 0x60)
    //   [100:132] data length     (≥ 4)
    //   [132:136] inner selector
    uint256 private constant SIMPLE_DATA_OFFSET = 0x60;
    uint256 private constant SIMPLE_INNER_SELECTOR_AT = 132;
    uint256 private constant SIMPLE_MIN_LENGTH = 136;

    // ── ERC-7579 execute(bytes32,bytes) layout ───────────────────────────────
    //
    //   [0  :  4] outer selector
    //   [4  : 36] mode (bytes32) — byte 0 = callType, byte 1 = execType, rest unused
    //   [36 : 68] data offset    (canonical = 0x40)
    //   [68 :100] data length    (≥ 56 = target(20) + value(32) + selector(4))
    //   executionData is abi.encodePacked(target, value, callData):
    //     [100:120] target
    //     [120:152] value
    //     [152:156] inner selector
    uint256 private constant ERC7579_DATA_OFFSET = 0x40;
    uint256 private constant ERC7579_TARGET_AT = 100;
    uint256 private constant ERC7579_INNER_SELECTOR_AT = 152;
    uint256 private constant ERC7579_MIN_EXEC_DATA_LEN = 56;
    uint256 private constant ERC7579_MIN_LENGTH = 156;
    bytes1 private constant ERC7579_CALLTYPE_SINGLE = 0x00;

    // ── Sponsored inner-selector allowlist ───────────────────────────────────
    // Only non-owner, user-facing selectors are sponsorable. Owner-only admin ops
    // are excluded so an attacker cannot drain an org's gas budget via reverting calls.
    //
    // Donate / cancelContribution / refund are intentionally NOT sponsored:
    // the frontend runs them as direct EOA calls because the ERC-20 token holder
    // (msg.sender) must match the donor identity, which can't happen via a smart
    // account when permit is ECDSA-only (USDC FiatToken).

    // CGToken user ops (ERC-1155 + ERC-1155Burnable)
    bytes4 private constant SEL_SAFE_TRANSFER_FROM =
        bytes4(keccak256("safeTransferFrom(address,address,uint256,uint256,bytes)"));
    bytes4 private constant SEL_SAFE_BATCH_TRANSFER_FROM =
        bytes4(keccak256("safeBatchTransferFrom(address,address,uint256[],uint256[],bytes)"));
    bytes4 private constant SEL_SET_APPROVAL_FOR_ALL = bytes4(keccak256("setApprovalForAll(address,bool)"));
    bytes4 private constant SEL_BURN = bytes4(keccak256("burn(address,uint256,uint256)"));
    bytes4 private constant SEL_BURN_BATCH = bytes4(keccak256("burnBatch(address,uint256[],uint256[])"));

    // ── State ─────────────────────────────────────────────────────────────────

    /// @notice The ERC-4337 EntryPoint singleton this paymaster is registered with.
    IEntryPoint public immutable entryPoint;

    /// @notice The Chain.Giving registry used to verify org and program addresses.
    CGRegistry public immutable registry;

    /// @notice Per-org internal gas budget (accounting only; actual ETH lives at EntryPoint).
    mapping(address org => uint256) public orgBalance;

    /// @notice Who may withdraw or reassign an org's budget.
    ///         address(0) means the CGPaymaster owner manages the org (default).
    mapping(address org => address) public orgManager;

    /// @notice Emit LowBalance when an org's remaining budget falls below this value (in wei).
    uint256 public lowBalanceThreshold;

    // ── Events ────────────────────────────────────────────────────────────────

    event Deposited(address indexed org, uint256 amount, address indexed depositor);
    event GasCharged(address indexed org, uint256 actualCost, uint256 remainingBalance);
    event LowBalance(address indexed org, uint256 balance);
    event Withdrawn(address indexed org, uint256 amount, address indexed to);
    event ManagementTransferred(address indexed org, address indexed newManager);
    event LowBalanceThresholdSet(uint256 threshold);

    // ── Errors ────────────────────────────────────────────────────────────────

    error OnlyEntryPoint();
    error NotOrgManager();
    error NotRegisteredOrg();
    error InsufficientOrgBalance(uint256 available, uint256 required);
    error InvalidCallTarget();
    error InvalidCallData();
    error InvalidPaymasterData();

    // ── Constructor ───────────────────────────────────────────────────────────

    constructor(IEntryPoint entryPoint_, CGRegistry registry_, uint256 lowBalanceThreshold_) Ownable(msg.sender) {
        entryPoint = entryPoint_;
        registry = registry_;
        lowBalanceThreshold = lowBalanceThreshold_;
    }

    // ── Modifiers ─────────────────────────────────────────────────────────────

    modifier onlyEntryPoint() {
        if (msg.sender != address(entryPoint)) revert OnlyEntryPoint();
        _;
    }

    // ── Funding ───────────────────────────────────────────────────────────────

    /// @notice Top up an org's gas budget. Sends ETH to the EntryPoint under this paymaster's deposit.
    ///         Callable by anyone — the registry owner tops up orgs as a managed service.
    /// @param org The CGOrganization address to credit.
    function depositFor(address org) external payable {
        if (!registry.isOrganization(org)) revert NotRegisteredOrg();
        orgBalance[org] += msg.value;
        entryPoint.depositTo{ value: msg.value }(address(this));
        emit Deposited(org, msg.value, msg.sender);
    }

    // ── Withdrawal ────────────────────────────────────────────────────────────

    /// @notice Withdraw unused ETH from an org's budget. Only callable by the org's manager.
    function withdraw(address org, address payable to, uint256 amount) external {
        if (msg.sender != _managerOf(org)) revert NotOrgManager();
        if (orgBalance[org] < amount) revert InsufficientOrgBalance(orgBalance[org], amount);

        orgBalance[org] -= amount;
        entryPoint.withdrawTo(to, amount);
        emit Withdrawn(org, amount, to);
    }

    // ── Management ────────────────────────────────────────────────────────────

    /// @notice Hand over management of an org's gas budget to a new address.
    function transferManagement(address org, address newManager) external {
        if (msg.sender != _managerOf(org)) revert NotOrgManager();
        orgManager[org] = newManager;
        emit ManagementTransferred(org, newManager);
    }

    /// @notice Update the low-balance warning threshold.
    function setLowBalanceThreshold(uint256 threshold) external onlyOwner {
        lowBalanceThreshold = threshold;
        emit LowBalanceThresholdSet(threshold);
    }

    // ── ERC-4337 Paymaster interface (v0.7) ───────────────────────────────────

    /// @notice Called by the EntryPoint before UserOperation execution.
    ///         Validates the sponsoring org has sufficient budget and that the call targets
    ///         a contract owned by that org. Reserves the maximum possible gas cost.
    function validatePaymasterUserOp(
        PackedUserOperation calldata userOp,
        bytes32,
        uint256 maxCost
    ) external onlyEntryPoint returns (bytes memory context, uint256 validationData) {
        if (userOp.paymasterAndData.length < ORG_DATA_END) revert InvalidPaymasterData();
        address org = address(bytes20(userOp.paymasterAndData[ORG_DATA_OFFSET:ORG_DATA_END]));

        if (!registry.isOrganization(org)) revert NotRegisteredOrg();
        if (orgBalance[org] < maxCost) revert InsufficientOrgBalance(orgBalance[org], maxCost);
        if (!_isValidCall(userOp.callData, CGOrganization(org))) revert InvalidCallTarget();

        // Reserve the worst-case cost; postOp refunds the unused portion.
        orgBalance[org] -= maxCost;

        return (abi.encode(org, maxCost), 0);
    }

    /// @notice Called by the EntryPoint after UserOperation execution.
    /// @dev    v0.7 signature includes `actualUserOpFeePerGas` (informational; we don't use it).
    ///         When `mode == postOpReverted`, the EntryPoint is retrying after the FIRST postOp
    ///         call reverted; crediting again would double-refund. We forfeit the reserve.
    function postOp(
        PostOpMode mode,
        bytes calldata context,
        uint256 actualGasCost,
        uint256 /* actualUserOpFeePerGas */
    ) external onlyEntryPoint {
        if (mode == PostOpMode.postOpReverted) return;

        (address org, uint256 reserved) = abi.decode(context, (address, uint256));

        // Defensive: the EntryPoint should never charge more than was reserved, but guard
        // against under-flow so a buggy entrypoint cannot zero out the org balance.
        uint256 charge = actualGasCost > reserved ? reserved : actualGasCost;

        unchecked {
            orgBalance[org] += reserved - charge;
        }

        uint256 remaining = orgBalance[org];
        emit GasCharged(org, charge, remaining);

        if (remaining < lowBalanceThreshold) {
            emit LowBalance(org, remaining);
        }
    }

    // ── Views ─────────────────────────────────────────────────────────────────

    /// @notice Total ETH deposited at the EntryPoint under this paymaster's account.
    function totalDeposit() external view returns (uint256) {
        return entryPoint.balanceOf(address(this));
    }

    /// @notice Returns the effective manager for an org's budget.
    function managerOf(address org) external view returns (address) {
        return _managerOf(org);
    }

    // ── Internal ──────────────────────────────────────────────────────────────

    function _managerOf(address org) internal view returns (address) {
        address m = orgManager[org];
        return m == address(0) ? owner() : m;
    }

    /// @dev Validates callData encodes one of the supported execute selectors, decodes the
    ///      inner call, and checks it targets an org-owned contract with an allowlisted
    ///      inner selector. Rejects non-canonical ABI encodings to keep offsets fixed.
    function _isValidCall(bytes calldata callData, CGOrganization org) internal view returns (bool) {
        if (callData.length < 4) revert InvalidCallData();
        bytes4 outerSel = bytes4(callData[0:4]);

        address target;
        bytes4 innerSelector;

        if (outerSel == EXECUTE_SIMPLE) {
            if (callData.length < SIMPLE_MIN_LENGTH) revert InvalidCallData();

            uint256 dataOffset = uint256(bytes32(callData[68:100]));
            if (dataOffset != SIMPLE_DATA_OFFSET) revert InvalidCallData();
            uint256 dataLength = uint256(bytes32(callData[100:132]));
            if (dataLength < 4) revert InvalidCallData();

            target = address(uint160(uint256(bytes32(callData[4:36]))));
            innerSelector = bytes4(callData[SIMPLE_INNER_SELECTOR_AT:SIMPLE_INNER_SELECTOR_AT + 4]);
        } else if (outerSel == EXECUTE_ERC7579) {
            if (callData.length < ERC7579_MIN_LENGTH) revert InvalidCallData();

            // Reject batch (0x01) and delegatecall (0xff) in v1
            if (callData[4] != ERC7579_CALLTYPE_SINGLE) revert InvalidCallData();

            uint256 dataOffset = uint256(bytes32(callData[36:68]));
            if (dataOffset != ERC7579_DATA_OFFSET) revert InvalidCallData();
            uint256 dataLength = uint256(bytes32(callData[68:100]));
            if (dataLength < ERC7579_MIN_EXEC_DATA_LEN) revert InvalidCallData();
            if (callData.length < 100 + dataLength) revert InvalidCallData();

            target = address(bytes20(callData[ERC7579_TARGET_AT:ERC7579_TARGET_AT + 20]));
            innerSelector = bytes4(callData[ERC7579_INNER_SELECTOR_AT:ERC7579_INNER_SELECTOR_AT + 4]);
        } else {
            revert InvalidCallData();
        }

        if (!_isSponsoredSelector(innerSelector)) revert InvalidCallData();
        return _isOrgContract(org, target);
    }

    /// @dev Allowlist of inner selectors the paymaster will sponsor. Limited to user-facing
    ///      flows so owner-only admin reverts cannot drain an org's budget.
    function _isSponsoredSelector(bytes4 sel) internal pure returns (bool) {
        return
            sel == SEL_SAFE_TRANSFER_FROM ||
            sel == SEL_SAFE_BATCH_TRANSFER_FROM ||
            sel == SEL_SET_APPROVAL_FOR_ALL ||
            sel == SEL_BURN ||
            sel == SEL_BURN_BATCH;
    }

    /// @dev Returns true if `target` is a contract that belongs to `org`:
    ///        - the org contract itself
    ///        - a CGProgram created by the org
    ///        - a CGToken, CGDistribution, or CGCrowdfunding owned by one of the org's programs
    ///          (all are Ownable with their parent CGProgram as owner)
    function _isOrgContract(CGOrganization org, address target) internal view returns (bool) {
        if (target == address(org)) return true;
        if (org.isProgram(target)) return true;
        if (target.code.length == 0) return false;
        try Ownable(target).owner() returns (address parent) {
            return org.isProgram(parent);
        } catch {
            return false;
        }
    }
}

contracts/CGProgram.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { IERC1155 } from "@openzeppelin/contracts/token/ERC1155/IERC1155.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { IERC20Permit } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { CGToken } from "./CGToken.sol";
import { CGCrowdfunding } from "./CGCrowdfunding.sol";
import { CGDistribution } from "./CGDistribution.sol";
import { CGComponentFactory } from "./CGComponentFactory.sol";

/// @notice Minimal subset of Uniswap Permit2 used for SignatureTransfer flows.
///         Permit2 is deterministically deployed at the same address on every
///         supported chain; see https://github.com/Uniswap/permit2.
interface IPermit2 {
    struct TokenPermissions {
        address token;
        uint256 amount;
    }
    struct PermitTransferFrom {
        TokenPermissions permitted;
        uint256 nonce;
        uint256 deadline;
    }
    struct SignatureTransferDetails {
        address to;
        uint256 requestedAmount;
    }
    function permitTransferFrom(
        PermitTransferFrom calldata permit,
        SignatureTransferDetails calldata transferDetails,
        address owner,
        bytes calldata signature
    ) external;
}

/// @title CGProgram — Orchestrates crowdfunding and ERC-1155 token distributions
/// @notice Top-level contract tying one crowdfunding to one-or-more distributions.
///         Each distribution uses a specific token type from the shared CGToken contract.
///         Child contracts are deployed via external factories to keep bytecode under the
///         24 KB Spurious Dragon limit.
contract CGProgram is Ownable {
    using SafeERC20 for IERC20;

    enum State {
        ACTIVE,
        EXECUTING,
        COMPLETED,
        CANCELLED
    }

    struct TokenTypeInfo {
        uint256 tokenId;
        string name;
        string symbol;
        uint256 maxSupply;
        uint256 totalMinted;
        string uri;
        bool transferable;
        bool burnable;
    }

    struct CrowdfundingInfo {
        address addr;
        address currency;
        uint256 fundingTarget;
        uint256 deadline;
        CGCrowdfunding.State state;
        uint256 totalRaised;
        uint256 totalTracked;
        bool isFunded;
    }

    struct DistributionInfo {
        address addr;
        uint256 tokenId;
        CGDistribution.State state;
        uint256 beneficiaryCount;
        uint256 totalRequired;
        address[] beneficiaries;
        uint256[] amounts;
    }

    string public name;
    bool public immutable lockDistributions;
    CGComponentFactory public immutable componentFactory;

    /// @notice Canonical Permit2 address — same on every chain via CREATE2 deploy.
    ///         Used by donateWithPermit2 to bypass per-program approvals.
    IPermit2 public constant PERMIT2 = IPermit2(0x000000000022D473030F116dDEE9F6B43aC78BA3);
    CGToken public token;
    CGCrowdfunding public crowdfunding;
    CGDistribution[] public distributions;
    State public state;

    event ProgramCreated(string name, address token, bool lockDistributions);
    event TokenTypeDefined(
        uint256 indexed tokenId,
        string name,
        string symbol,
        uint256 maxSupply,
        bool transferable,
        bool burnable
    );
    event CrowdfundingSet(address crowdfunding, address currency);
    event DistributionCreated(uint256 index, address distribution, uint256 tokenId);
    event DistributionDeleted(uint256 index, address distribution);
    event ProgramExecuted();
    event ProgramCancelled();

    error ProgramNotActive();
    error CrowdfundingAlreadySet();
    error NoCrowdfunding();
    error NoDistributions();
    error DistributionNotReady(uint256 index);
    error DistributionsLocked();
    error ExceedsTotalSupply(uint256 tokenId, uint256 totalRequired, uint256 maxSupply);
    error DistributionAlreadyDistributed(uint256 index);
    error ContributionsExist();

    constructor(
        address owner_,
        string memory name_,
        bool lockDistributions_,
        CGComponentFactory componentFactory_
    ) Ownable(owner_) {
        name = name_;
        lockDistributions = lockDistributions_;
        componentFactory = componentFactory_;

        token = CGToken(componentFactory_.createToken(address(this)));
        state = State.ACTIVE;

        emit ProgramCreated(name_, address(token), lockDistributions_);
    }

    /// @notice Define a new ERC-1155 token type on the program's token contract.
    function defineTokenType(
        string calldata name_,
        string calldata symbol_,
        uint256 maxSupply_,
        string calldata uri_,
        bool transferable_,
        bool burnable_
    ) external onlyOwner returns (uint256 tokenId) {
        if (state != State.ACTIVE) revert ProgramNotActive();
        tokenId = token.defineTokenType(name_, symbol_, maxSupply_, uri_, transferable_, burnable_);
        emit TokenTypeDefined(tokenId, name_, symbol_, maxSupply_, transferable_, burnable_);
    }

    /// @notice Deploy and attach a CGCrowdfunding for the given ERC-20 currency.
    function setCrowdfunding(address currency_, uint256 target_, uint256 deadline_) external onlyOwner {
        if (state != State.ACTIVE) revert ProgramNotActive();
        if (address(crowdfunding) != address(0)) revert CrowdfundingAlreadySet();

        crowdfunding = CGCrowdfunding(
            componentFactory.createCrowdfunding(address(this), currency_, target_, deadline_)
        );
        emit CrowdfundingSet(address(crowdfunding), currency_);
    }

    /// @notice Deploy a new CGDistribution for a specific token type.
    function createDistribution(uint256 tokenId_) external onlyOwner returns (address) {
        if (state != State.ACTIVE) revert ProgramNotActive();
        if (lockDistributions && _crowdfundingHasContributions()) revert DistributionsLocked();

        // Validate the token type exists
        token.getTokenType(tokenId_);

        CGDistribution dist = CGDistribution(
            componentFactory.createDistribution(address(this), IERC1155(address(token)), tokenId_)
        );
        distributions.push(dist);

        // Allow the distribution contract to transfer soulbound tokens on behalf of the program.
        token.setAuthorizedTransferrer(address(dist), true);

        uint256 index = distributions.length - 1;
        emit DistributionCreated(index, address(dist), tokenId_);
        return address(dist);
    }

    function setBeneficiaries(
        uint256 distributionIndex,
        address[] calldata beneficiaries_,
        uint256[] calldata amounts_
    ) external onlyOwner {
        if (state != State.ACTIVE) revert ProgramNotActive();
        if (lockDistributions && _crowdfundingHasContributions()) revert DistributionsLocked();

        CGDistribution dist = distributions[distributionIndex];
        dist.setBeneficiaries(beneficiaries_, amounts_);
        _validateSupplyCap(dist.tokenId());
    }

    function addBeneficiaries(
        uint256 distributionIndex,
        address[] calldata beneficiaries_,
        uint256[] calldata amounts_
    ) external onlyOwner {
        if (state != State.ACTIVE) revert ProgramNotActive();
        if (lockDistributions && _crowdfundingHasContributions()) revert DistributionsLocked();

        CGDistribution dist = distributions[distributionIndex];
        dist.addBeneficiaries(beneficiaries_, amounts_);
        _validateSupplyCap(dist.tokenId());
    }

    function removeBeneficiaries(uint256 distributionIndex, address[] calldata toRemove_) external onlyOwner {
        if (state != State.ACTIVE) revert ProgramNotActive();
        if (lockDistributions && _crowdfundingHasContributions()) revert DistributionsLocked();

        distributions[distributionIndex].removeBeneficiaries(toRemove_);
    }

    function deleteDistribution(uint256 distributionIndex) external onlyOwner {
        if (state != State.ACTIVE) revert ProgramNotActive();
        CGDistribution.State distState = distributions[distributionIndex].state();
        if (distState == CGDistribution.State.DISTRIBUTED) revert DistributionAlreadyDistributed(distributionIndex);
        if (distState == CGDistribution.State.READY && _crowdfundingHasContributions()) revert ContributionsExist();

        address deleted = address(distributions[distributionIndex]);

        token.setAuthorizedTransferrer(deleted, false);

        uint256 last = distributions.length - 1;
        if (distributionIndex != last) {
            distributions[distributionIndex] = distributions[last];
        }
        distributions.pop();

        emit DistributionDeleted(distributionIndex, deleted);
    }

    function markDistributionReady(uint256 distributionIndex) external onlyOwner {
        if (state != State.ACTIVE) revert ProgramNotActive();

        CGDistribution dist = distributions[distributionIndex];
        uint256 required = dist.totalRequired();
        uint256 distTokenId = dist.tokenId();

        token.mint(address(dist), distTokenId, required);
        dist.markReady();
    }

    /// @notice Donate ERC-20 tokens through the program. Caller must approve the program for `amount`.
    ///         Enforces lock-distributions gating.
    function donate(uint256 amount) external {
        _preDonateChecks();
        IERC20 currency = crowdfunding.token();
        currency.safeTransferFrom(msg.sender, address(this), amount);
        currency.forceApprove(address(crowdfunding), amount);
        crowdfunding.donateFor(msg.sender, amount);
    }

    /// @notice EIP-2612 permit + donate in one transaction. Donor signs a permit authorizing
    ///         the PROGRAM (not the crowdfunding) to spend `amount`. Permit is wrapped in
    ///         try/catch to defend against permit-front-running griefing.
    function donateWithPermit(
        uint256 amount,
        uint256 permitDeadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external {
        _preDonateChecks();
        IERC20 currency = crowdfunding.token();
        try IERC20Permit(address(currency)).permit(msg.sender, address(this), amount, permitDeadline, v, r, s) {} catch {}
        currency.safeTransferFrom(msg.sender, address(this), amount);
        currency.forceApprove(address(crowdfunding), amount);
        crowdfunding.donateFor(msg.sender, amount);
    }

    /// @notice Permit2-based donate. Donor signs a Permit2 PermitTransferFrom authorizing
    ///         this program to pull `amount` of the crowdfunding currency. Requires a
    ///         one-time `approve(PERMIT2, …)` on the token; subsequent donations need
    ///         only a signature. Wallets recognize Permit2 signatures and render a
    ///         non-scary UI (the spender is the well-known Permit2 contract, not this
    ///         unverified program).
    function donateWithPermit2(uint256 amount, uint256 nonce, uint256 deadline, bytes calldata signature) external {
        _preDonateChecks();
        IERC20 currency = crowdfunding.token();
        PERMIT2.permitTransferFrom(
            IPermit2.PermitTransferFrom({
                permitted: IPermit2.TokenPermissions({ token: address(currency), amount: amount }),
                nonce: nonce,
                deadline: deadline
            }),
            IPermit2.SignatureTransferDetails({ to: address(this), requestedAmount: amount }),
            msg.sender,
            signature
        );
        currency.forceApprove(address(crowdfunding), amount);
        crowdfunding.donateFor(msg.sender, amount);
    }

    function _preDonateChecks() internal view {
        if (state != State.ACTIVE) revert ProgramNotActive();
        if (address(crowdfunding) == address(0)) revert NoCrowdfunding();

        if (lockDistributions) {
            if (distributions.length == 0) revert NoDistributions();
            for (uint256 i = 0; i < distributions.length; i++) {
                if (distributions[i].state() != CGDistribution.State.READY) revert DistributionNotReady(i);
            }
        }
    }

    /// @notice Withdraw funds and distribute tokens — all in one transaction.
    /// @dev    crowdfunding.withdraw() auto-syncs direct transfers and reverts with
    ///         NotInState if the campaign is still under target after sync.
    function execute() external onlyOwner {
        if (state != State.ACTIVE) revert ProgramNotActive();
        if (address(crowdfunding) == address(0)) revert NoCrowdfunding();
        if (distributions.length == 0) revert NoDistributions();

        for (uint256 i = 0; i < distributions.length; i++) {
            if (distributions[i].state() != CGDistribution.State.READY) revert DistributionNotReady(i);
        }

        // Act as a reentrancy guard: external calls below (withdraw, distribute)
        // will revert if they re-enter any function guarded by `ProgramNotActive`.
        state = State.EXECUTING;

        crowdfunding.withdraw(owner());

        for (uint256 i = 0; i < distributions.length; i++) {
            distributions[i].distribute();
        }

        state = State.COMPLETED;
        emit ProgramExecuted();
    }

    /// @notice Owner-only wrapper around crowdfunding.returnUntracked(to, amount).
    ///         Lets the program owner refund stray direct transfers identified off-chain.
    function returnUntracked(address to, uint256 amount) external onlyOwner {
        if (address(crowdfunding) == address(0)) revert NoCrowdfunding();
        crowdfunding.returnUntracked(to, amount);
    }

    /// @notice Owner-only wrapper around crowdfunding.sweepUntracked(to). Only callable
    ///         after the crowdfunding has been cancelled (enforced by the crowdfunding).
    function sweepUntracked(address to) external onlyOwner {
        if (address(crowdfunding) == address(0)) revert NoCrowdfunding();
        crowdfunding.sweepUntracked(to);
    }

    function cancel() external onlyOwner {
        if (state != State.ACTIVE) revert ProgramNotActive();

        state = State.CANCELLED;

        if (address(crowdfunding) != address(0) && crowdfunding.state() == CGCrowdfunding.State.ACTIVE) {
            crowdfunding.cancel();
        }

        emit ProgramCancelled();
    }

    function distributionCount() external view returns (uint256) {
        return distributions.length;
    }

    function getTokenTypes() external view returns (TokenTypeInfo[] memory infos) {
        uint256 count = token.nextTokenId();
        infos = new TokenTypeInfo[](count);
        for (uint256 i = 0; i < count; i++) {
            CGToken.TokenType memory tt = token.getTokenType(i);
            infos[i] = TokenTypeInfo({
                tokenId: i,
                name: tt.name,
                symbol: tt.symbol,
                maxSupply: tt.maxSupply,
                totalMinted: tt.totalMinted,
                uri: token.uri(i),
                transferable: tt.transferable,
                burnable: tt.burnable
            });
        }
    }

    function getCrowdfundingInfo() external view returns (CrowdfundingInfo memory info) {
        if (address(crowdfunding) == address(0)) return info;

        info = CrowdfundingInfo({
            addr: address(crowdfunding),
            currency: address(crowdfunding.token()),
            fundingTarget: crowdfunding.fundingTarget(),
            deadline: crowdfunding.deadline(),
            state: crowdfunding.state(),
            totalRaised: crowdfunding.totalRaised(),
            totalTracked: crowdfunding.totalTracked(),
            isFunded: crowdfunding.isFunded()
        });
    }

    function getDistributionInfo(uint256 index) public view returns (DistributionInfo memory) {
        CGDistribution dist = distributions[index];
        return
            DistributionInfo({
                addr: address(dist),
                tokenId: dist.tokenId(),
                state: dist.state(),
                beneficiaryCount: dist.beneficiaryCount(),
                totalRequired: dist.totalRequired(),
                beneficiaries: dist.getBeneficiaries(),
                amounts: dist.getAmounts()
            });
    }

    function getAllDistributionsInfo() external view returns (DistributionInfo[] memory infos) {
        infos = new DistributionInfo[](distributions.length);
        for (uint256 i = 0; i < distributions.length; i++) {
            infos[i] = getDistributionInfo(i);
        }
    }

    function _validateSupplyCap(uint256 distTokenId_) internal view {
        CGToken.TokenType memory tt = token.getTokenType(distTokenId_);
        if (tt.maxSupply > 0) {
            uint256 aggregateRequired = _totalRequiredForToken(distTokenId_);
            if (aggregateRequired > tt.maxSupply)
                revert ExceedsTotalSupply(distTokenId_, aggregateRequired, tt.maxSupply);
        }
    }

    function _crowdfundingHasContributions() internal view returns (bool) {
        return address(crowdfunding) != address(0) && crowdfunding.totalRaised() > 0;
    }

    function _totalRequiredForToken(uint256 tokenId_) internal view returns (uint256 total) {
        for (uint256 i = 0; i < distributions.length; i++) {
            CGDistribution dist = distributions[i];
            if (dist.tokenId() == tokenId_) {
                total += dist.totalRequired();
            }
        }
    }
}

contracts/CGProgramFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { CGProgram } from "./CGProgram.sol";
import { CGComponentFactory } from "./CGComponentFactory.sol";

/// @title CGProgramFactory — Deploys CGProgram instances
/// @notice Only authorized callers (CGOrganizations created via CGRegistry) can use createProgram.
///         Ownership should be transferred to CGRegistry after deployment.
///         A shared CGComponentFactory is injected so CGProgram never uses `new` directly,
///         keeping every contract under the 24 KB Spurious Dragon limit.
contract CGProgramFactory is Ownable {
    CGComponentFactory public immutable componentFactory;

    mapping(address => bool) public authorizedCallers;

    event ProgramDeployed(address indexed program, address indexed owner, string name);
    event CallerAuthorized(address indexed caller, bool authorized);

    error Unauthorized();

    constructor(CGComponentFactory componentFactory_) Ownable(msg.sender) {
        componentFactory = componentFactory_;
    }

    /// @notice Authorize or deauthorize a caller (e.g. a CGOrganization). Only callable by owner (CGRegistry).
    function authorizeCaller(address caller_, bool authorized_) external onlyOwner {
        authorizedCallers[caller_] = authorized_;
        emit CallerAuthorized(caller_, authorized_);
    }

    /// @notice Deploy a new CGProgram. Only callable by authorized callers.
    function createProgram(address owner_, string calldata name_, bool lockDistributions_) external returns (address) {
        if (!authorizedCallers[msg.sender]) revert Unauthorized();
        CGProgram program = new CGProgram(owner_, name_, lockDistributions_, componentFactory);
        address addr = address(program);
        emit ProgramDeployed(addr, owner_, name_);
        return addr;
    }
}

contracts/CGRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { CGOrganization } from "./CGOrganization.sol";
import { CGProgramFactory } from "./CGProgramFactory.sol";

/// @title CGRegistry — Directory of all CGOrganization instances
/// @notice Only the registry owner (deployer) can create organizations.
contract CGRegistry is Ownable {
    CGProgramFactory public immutable programFactory;
    address[] public organizations;
    mapping(address => bool) public isOrganization;

    event OrganizationCreated(address indexed organization, address indexed owner, string name);
    event OrganizationAdded(address indexed organization);
    event OrganizationRemoved(address indexed organization);

    error EmptyName();
    error ZeroAddress();
    error NotOrganization();
    error AlreadyOrganization();

    constructor(CGProgramFactory programFactory_) Ownable(msg.sender) {
        programFactory = programFactory_;
    }

    /// @notice Deploy a new CGOrganization with the given owner. Only callable by registry owner.
    function createOrganization(string calldata name_, address owner_) external onlyOwner returns (address) {
        if (bytes(name_).length == 0) revert EmptyName();
        if (owner_ == address(0)) revert ZeroAddress();

        CGOrganization org = new CGOrganization(owner_, name_, programFactory);
        address addr = address(org);
        organizations.push(addr);
        isOrganization[addr] = true;

        // Authorize the new organization to use the factory
        programFactory.authorizeCaller(addr, true);

        emit OrganizationCreated(addr, owner_, name_);
        return addr;
    }

    /// @notice Add an existing CGOrganization by address (e.g. to re-add a previously removed org).
    ///         Only callable by registry owner. Re-authorizes the org to use the program factory.
    function addOrganization(address organization_) external onlyOwner {
        if (organization_ == address(0)) revert ZeroAddress();
        if (isOrganization[organization_]) revert AlreadyOrganization();

        organizations.push(organization_);
        isOrganization[organization_] = true;
        programFactory.authorizeCaller(organization_, true);

        emit OrganizationAdded(organization_);
    }

    /// @notice Remove an organization from the registry. Only callable by registry owner.
    /// @dev Revokes the organization's authorization to use the program factory. Does not
    ///      affect already-deployed programs owned by that organization.
    function removeOrganization(address organization_) external onlyOwner {
        if (!isOrganization[organization_]) revert NotOrganization();

        uint256 len = organizations.length;
        for (uint256 i = 0; i < len; i++) {
            if (organizations[i] == organization_) {
                if (i != len - 1) organizations[i] = organizations[len - 1];
                organizations.pop();
                break;
            }
        }

        delete isOrganization[organization_];
        programFactory.authorizeCaller(organization_, false);

        emit OrganizationRemoved(organization_);
    }

    function organizationCount() external view returns (uint256) {
        return organizations.length;
    }

    /// @notice Paginated read of organization addresses.
    function getOrganizations(uint256 offset, uint256 limit) external view returns (address[] memory) {
        uint256 len = organizations.length;
        if (offset >= len) return new address[](0);

        uint256 end = offset + limit;
        if (end > len) end = len;
        uint256 size = end - offset;

        address[] memory result = new address[](size);
        for (uint256 i = 0; i < size; i++) {
            result[i] = organizations[offset + i];
        }
        return result;
    }
}

contracts/CGToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { ERC1155 } from "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import { ERC1155Burnable } from "@openzeppelin/contracts/token/ERC1155/extensions/ERC1155Burnable.sol";
import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";

/// @title CGToken — ERC-1155 multi-token for a Chain.Giving program
/// @notice One deployment per program. Supports multiple token types in a single contract.
///         Each type is configured independently: unlimited supply (fungible), capped supply
///         (semi-fungible badges), or supply of 1 (unique NFT). Owner (typically CGProgram)
///         controls type definition and minting. Each type can independently enable/disable
///         user transfers and burns.
contract CGToken is ERC1155Burnable, Ownable {
    struct TokenType {
        string name;
        string symbol;
        uint256 maxSupply; // 0 = unlimited; 1 = unique NFT; N = capped semi-fungible
        uint256 totalMinted;
        bool transferable; // true = holders can transfer; false = soulbound (owner can always transfer)
        bool burnable; // true = holders can burn; false = burn disabled (owner can always burn)
    }

    mapping(uint256 => TokenType) public tokenTypes;
    mapping(uint256 => string) private _uris;
    mapping(address => bool) public authorizedTransferrers;
    uint256 public nextTokenId;

    event TokenTypeDefined(
        uint256 indexed tokenId,
        string name,
        string symbol,
        uint256 maxSupply,
        bool transferable,
        bool burnable
    );
    event AuthorizedTransferrerSet(address indexed account, bool authorized);

    error UnknownTokenType(uint256 tokenId);
    error ExceedsMaxSupply(uint256 tokenId, uint256 requested, uint256 remaining);
    error TransferDisabled(uint256 tokenId);
    error BurnDisabled(uint256 tokenId);

    constructor(address owner_) ERC1155("") Ownable(owner_) {}

    /// @notice Grant or revoke an address's ability to bypass soulbound restrictions.
    ///         Used to allow CGDistribution contracts to transfer non-transferable tokens.
    function setAuthorizedTransferrer(address account, bool authorized) external onlyOwner {
        authorizedTransferrers[account] = authorized;
        emit AuthorizedTransferrerSet(account, authorized);
    }

    /// @notice Define a new token type. Returns the auto-assigned tokenId (starts at 0).
    /// @param name_         Display name (e.g. "Food Voucher")
    /// @param symbol_       Short symbol (e.g. "FOOD")
    /// @param maxSupply_    Hard cap on total minted. 0 = unlimited (fungible), 1 = unique NFT,
    ///                      N = capped supply (badges, tickets, etc.)
    /// @param uri_          Optional per-type metadata URI; falls back to contract-level URI if empty
    /// @param transferable_ Whether holders can transfer tokens (owner/program can always transfer)
    /// @param burnable_     Whether holders can burn tokens (owner/program can always burn)
    function defineTokenType(
        string calldata name_,
        string calldata symbol_,
        uint256 maxSupply_,
        string calldata uri_,
        bool transferable_,
        bool burnable_
    ) external onlyOwner returns (uint256 tokenId) {
        tokenId = nextTokenId++;
        tokenTypes[tokenId] = TokenType({
            name: name_,
            symbol: symbol_,
            maxSupply: maxSupply_,
            totalMinted: 0,
            transferable: transferable_,
            burnable: burnable_
        });
        if (bytes(uri_).length > 0) {
            _uris[tokenId] = uri_;
        }
        emit TokenTypeDefined(tokenId, name_, symbol_, maxSupply_, transferable_, burnable_);
    }

    /// @notice Mint tokens of a given type to a recipient. onlyOwner.
    function mint(address to, uint256 tokenId, uint256 amount) external onlyOwner {
        _validateMint(tokenId, amount);
        tokenTypes[tokenId].totalMinted += amount;
        _mint(to, tokenId, amount, "");
    }

    /// @notice Batch mint multiple token types in one call. onlyOwner.
    function mintBatch(address to, uint256[] calldata tokenIds, uint256[] calldata amounts) external onlyOwner {
        for (uint256 i = 0; i < tokenIds.length; i++) {
            _validateMint(tokenIds[i], amounts[i]);
            tokenTypes[tokenIds[i]].totalMinted += amounts[i];
        }
        _mintBatch(to, tokenIds, amounts, "");
    }

    /// @notice Per-type metadata URI; falls back to contract-level URI if none set.
    function uri(uint256 tokenId) public view override returns (string memory) {
        string memory tokenUri = _uris[tokenId];
        if (bytes(tokenUri).length > 0) return tokenUri;
        return super.uri(tokenId);
    }

    /// @notice Return full metadata for a token type.
    function getTokenType(uint256 tokenId) external view returns (TokenType memory) {
        if (tokenId >= nextTokenId) revert UnknownTokenType(tokenId);
        return tokenTypes[tokenId];
    }

    // ── Internal ─────────────────────────────────────────────────────────────

    function _validateMint(uint256 tokenId, uint256 amount) internal view {
        if (tokenId >= nextTokenId) revert UnknownTokenType(tokenId);
        TokenType storage tt = tokenTypes[tokenId];
        if (tt.maxSupply > 0 && tt.totalMinted + amount > tt.maxSupply)
            revert ExceedsMaxSupply(tokenId, amount, tt.maxSupply - tt.totalMinted);
    }

    /// @dev Enforce per-type transfer and burn restrictions.
    ///      Mints (from == 0) are always allowed (gated by onlyOwner on mint()).
    ///      The contract owner (CGProgram) and authorized transferrers (e.g. CGDistribution)
    ///      are always allowed to transfer and burn regardless of the flags.
    function _update(address from, address to, uint256[] memory ids, uint256[] memory values) internal override {
        bool isMint = from == address(0);
        bool isPrivileged = _msgSender() == owner() || authorizedTransferrers[_msgSender()];

        if (!isMint && !isPrivileged) {
            bool isBurn = to == address(0);
            for (uint256 i = 0; i < ids.length; i++) {
                if (ids[i] >= nextTokenId) revert UnknownTokenType(ids[i]);
                TokenType storage tt = tokenTypes[ids[i]];
                if (isBurn) {
                    if (!tt.burnable) revert BurnDisabled(ids[i]);
                } else {
                    if (!tt.transferable) revert TransferDisabled(ids[i]);
                }
            }
        }

        super._update(from, to, ids, values);
    }
}
